\begin{definition}[Clipping]
\label{def:clipping}
For any $M>0$ and $t\in\R$, we define the clipped version $\bar{t}$ of $t$ as
$$
\bar{t} = \begin{cases}
-M,& \mbox{if } t < -M \\
t, & \mbox{if } t \in [-M,M] \\
M, & \mbox{if } t > M.
\end{cases}
$$
Similarly, the clipped version $\bar{f}$ of a function $f : \X\rightarrow \R$ is defined as
$$
\forall x\in\X,\quad \bar{f}(x) = \overline{f(x)} = \begin{cases}
-M,& \mbox{if } f(x) < -M \\
f(x), & \mbox{if } f(x) \in [-M,M] \\
M, & \mbox{if } f(x) > M
\end{cases}
$$
and $\bar{\F}$ denotes the clipped function class $\{\bar{f} : f \in \F\}$.
\end{definition}

