\begin{lemma}\label{lem:uniformcovmonotone}
Let $\F$ be a uniform GC class from $\X$ into $[-M,M]$. Then, for any $\epsilon>0$ and any $q\in[1,\infty)\cup\{\infty\}$, the uniform covering numbers $\mathcal{N}_q(\epsilon, \F, n)$ form a non-decreasing function of $n$.
\end{lemma}

\begin{lemma}
\label{lem:coveringmax}
Given a sequence of $C$ real-valued function classes $\mathcal{A}_k$ with domain $\Z$, let $\mathcal{A}$ be either the pointwise maximum class $\{a\in\R^{\Z} : a(z) = \max_{k\in[C]} a_k(z) ,\ a_k \in\mathcal{A}_k\}$  or the pointwise minimum class $\{a\in\R^{\Z} : a(z) = \min_{k\in[C]} a_k(z) ,\ a_k \in\mathcal{A}_k\}$. Then, for any $q\geq 1$ and $q=\infty$,
$$
	\mathcal{N}(\epsilon, \mathcal{A}, d_{q,\g z_n}) \leq \prod_{k=1}^C \mathcal{N}\left(\frac{\epsilon}{C^{1/q}}, \mathcal{A}_k, d_{q,\g z_n}\right) .
$$
\end{lemma}

